// ==============================================================================
// Week 3: 인입 질의 전처리, 세션 식별자(Session ID) 할당 및 입력 정규화
// ==============================================================================
const input = $input.first().json;

// 1. HTTP Body에서 사용자 질의 추출 (다양한 필드 키 대응)
const promptText = input.body?.prompt || input.body?.query || input.prompt || input.query || input.body?.message || (typeof input.body === 'string' ? input.body : "대한전자 결제 DB 장애 상태 점검 및 대응 절차 안내 요청");

// 2. 세션 식별자(Session ID) 파싱 또는 자동 생성 (멀티턴 메모리 유지용)
const sessionId = input.body?.session_id || input.session_id || input.headers?.['x-session-id'] || `sess-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 7)}`;

// 3. 대상 고객사 힌트 및 서버 ID 메타데이터 추출 (옵션)
const targetCompany = input.body?.company_name || input.company_name || "";
const targetServerId = input.body?.server_id || input.server_id || "";

return [{
  json: {
    chatInput: String(promptText).trim(),
    sessionId: sessionId,
    targetCompany: targetCompany,
    targetServerId: targetServerId,
    received_at: new Date().toISOString()
  }
}];

// ==============================================================================
// Week 3: 에이전트 최종 실행 결과 구조화 및 감사 페이로드 패키징
// ==============================================================================
const agentOutput = $input.first().json;
const sessionContext = $('Extract Input and Session').item.json;

const rawOutputText = agentOutput.output || agentOutput.text || JSON.stringify(agentOutput);

return [{
  json: {
    status: "success",
    session_id: sessionContext.sessionId,
    query: sessionContext.chatInput,
    agent_report: rawOutputText,
    generated_at: new Date().toISOString(),
    orchestrator: "n8n-react-multi-tool-agent",
    tools_bound: [
      "lookup_customer_incident_history (Postgres Sub-workflow)",
      "fetch_server_metrics (Mock Enterprise API)",
      "search_enterprise_runbook (Qdrant Vector Store bge-m3)"
    ]
  }
}];

// ==============================================================================
// Week 3: 서브 워크플로우 - 고객 정보 및 티켓 목록 집계 후 JSON 직렬화
// ==============================================================================
const items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      found: false,
      message: "일치하는 고객사 정보를 찾을 수 없습니다. 기본 Standard 등급 및 SLA 240분을 적용합니다.",
      contract_tier: "Standard",
      sla_response_minutes: 240,
      recent_incidents: []
    }
  }];
}

const first = items[0].json;
const customerInfo = {
  customer_id: first.customer_id,
  company_name: first.company_name,
  contract_tier: first.contract_tier,
  is_vip: first.contract_tier === 'VIP',
  sla_response_minutes: first.sla_response_minutes,
  account_manager: first.account_manager_email
};

const incidents = [];
for (const row of items) {
  if (row.json.ticket_id && row.json.ticket_id !== 'NONE') {
    incidents.push({
      ticket_id: row.json.ticket_id,
      severity: row.json.severity,
      category: row.json.category,
      summary: row.json.ticket_summary,
      status: row.json.ticket_status,
      created_at: row.json.ticket_created_at
    });
  }
}

return [{
  json: {
    found: true,
    customer: customerInfo,
    recent_incident_count: incidents.length,
    recent_incidents: incidents,
    queried_at: new Date().toISOString()
  }
}];
